<?php
 namespace Slim\Middleware; class Flash extends \Slim\Middleware implements \ArrayAccess, \IteratorAggregate, \Countable { protected $settings; protected $messages; public function __construct($settings = array()) { $this->settings = array_merge(array('key' => 'slim.flash'), $settings); $this->messages = array( 'prev' => array(), 'next' => array(), 'now' => array() ); } public function call() { $this->loadMessages(); $env = $this->app->environment(); $env['slim.flash'] = $this; $this->next->call(); $this->save(); } public function now($key, $value) { $this->messages['now'][(string) $key] = $value; } public function set($key, $value) { $this->messages['next'][(string) $key] = $value; } public function keep() { foreach ($this->messages['prev'] as $key => $val) { $this->messages['next'][$key] = $val; } } public function save() { $_SESSION[$this->settings['key']] = $this->messages['next']; } public function loadMessages() { if (isset($_SESSION[$this->settings['key']])) { $this->messages['prev'] = $_SESSION[$this->settings['key']]; } } public function getMessages() { return array_merge($this->messages['prev'], $this->messages['now']); } public function offsetExists($offset) { $messages = $this->getMessages(); return isset($messages[$offset]); } public function offsetGet($offset) { $messages = $this->getMessages(); return isset($messages[$offset]) ? $messages[$offset] : null; } public function offsetSet($offset, $value) { $this->now($offset, $value); } public function offsetUnset($offset) { unset($this->messages['prev'][$offset], $this->messages['now'][$offset]); } public function getIterator() { $messages = $this->getMessages(); return new \ArrayIterator($messages); } public function count() { return count($this->getMessages()); } } 